use std::cmp::PartialEq;

fn remove_duplicates(nums: &Vec<i32>) -> usize {
    let n = nums.len();
    if n == 0 {
        return 0;
    }

    // Since nums is sorted (non-decreasing), distinct values occur at boundaries
    // where the value changes.
    let mut count: usize = 1;
    let mut prev = nums[0];

    for &x in nums.iter().skip(1) {
        if x != prev {
            count += 1;
            prev = x;
        }
    }

    count
}